#include <iostream>
#include <vector>
using namespace std;

vector<long long> build_difference(const vector<long long>& a) {
    int size = static_cast<int>(a.size());
    vector<long long> diff(size + 1, 0);
    for (int i = 0; i < size; ++i) {
        diff[i] += a[i];
        diff[i + 1] -= a[i];
    }
    return diff;
}

void add_range(vector<long long>& diff, int l, int r,
               long long amount) {
    diff[l] += amount;
    diff[r] -= amount;
}

vector<long long> restore_values(const vector<long long>& diff) {
    int size = static_cast<int>(diff.size()) - 1;
    vector<long long> a(size);
    long long cur = 0;
    for (int i = 0; i < size; ++i) {
        cur += diff[i];
        a[i] = cur;
    }
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size, q;
    cin >> size >> q;
    vector<long long> a(size);
    for (long long& value : a) {
        cin >> value;
    }
    vector<long long> diff = build_difference(a);
    for (int update = 0; update < q; ++update) {
        int l, r;
        long long amount;
        cin >> l >> r >> amount;
        add_range(diff, l - 1, r, amount);
    }
    a = restore_values(diff);
    for (int i = 0; i < size; ++i) {
        if (i > 0) {
            cout << ' ';
        }
        cout << a[i];
    }
    cout << '\n';
    return 0;
}

